namespace FoolLauncher {
 public static class JavaManagementTests {
  static void Assert(bool test,string message){if(!test)throw new Exception(message);}
  internal static void FakeExe(string path,bool x64=true){Directory.CreateDirectory(Path.GetDirectoryName(path));using(var file=new FileStream(path,FileMode.Create))using(var w=new BinaryWriter(file)){var bytes=new byte[256];file.Write(bytes,0,bytes.Length);file.Position=0;w.Write((ushort)0x5a4d);file.Position=60;w.Write(128);file.Position=128;w.Write(0x4550);w.Write((ushort)(x64?0x8664:0x14c));}}
  static JavaRuntime Fake(string home,int major,bool x64=true){string exe=Path.Combine(home,"bin","javaw.exe");FakeExe(exe,x64);File.WriteAllText(Path.Combine(home,"release"),"JAVA_VERSION=\""+(major==8?"1.8.0_504":major+".0.1")+"\"\n");return JavaManager.Inspect(exe);}
  static void Denied(Action job,string message){bool error=false;try{job();}catch(IOException){error=true;}catch(InvalidDataException){error=true;}Assert(error,message);}
  public static void Run(string parent){string root=Path.Combine(parent,"java-manager"),runtime=Path.Combine(root,"runtime");Directory.CreateDirectory(runtime);JavaRuntime j17=Fake(Path.Combine(runtime,"jdk17"),17),j21=Fake(Path.Combine(runtime,"jdk21"),21),j8=Fake(Path.Combine(root,"external-java8"),8),x86=Fake(Path.Combine(root,"external-java32"),17,false);
   Assert(j17!=null&&j17.Major==17&&j17.Architecture=="x64"&&x86.Architecture=="x86","PE/release Java detection failed");string bad=Path.Combine(root,"bad","javaw.exe");Directory.CreateDirectory(Path.GetDirectoryName(bad));File.WriteAllText(bad,"not Java");Assert(JavaManager.Inspect(bad)==null,"Unrecognized executable accepted as Java");
   var manager=new JavaManager(root);manager.Remember(new[]{j8,x86});var list=manager.List(false,CancellationToken.None);Assert(list.Length==4,"Managed/custom Java inventory lost entries");var cfg=new Dictionary<string,string>();JavaRuntime.Configure(root,"1.20.1",cfg,true);Assert(cfg["JavaVersion"]==j17.Version,"Automatic Java17 selection failed");JavaRuntime.Configure(root,"1.21.1",cfg,true);Assert(cfg["JavaVersion"]==j21.Version,"Automatic selection did not re-evaluate on next launch");
   manager.Use(j8);Assert(!new JavaManager(root).Settings.Automatic,"Manual Java policy not saved");JavaRuntime.Configure(root,"1.16.5",cfg,true);Assert(cfg["JavaPath"].Replace('/','\\')==j8.Path,"Manual Java not applied to instance config");Denied(()=>JavaRuntime.Configure(root,"1.20.1",cfg,true),"Incompatible manual Java silently substituted");Denied(()=>manager.Use(x86),"32-bit Java selected");manager.Use(j17);var saved=new JavaManager(root);Assert(!Path.IsPathRooted(saved.Settings.Selected),"Managed Java path not portable");
   File.Delete(j17.Path);Denied(()=>JavaRuntime.Configure(root,"1.20.1",cfg,true),"Missing manual Java silently substituted");Fake(Path.GetDirectoryName(Path.GetDirectoryName(j17.Path)),17);manager.Auto();JavaRuntime.Configure(root,"1.21.1",cfg,true);Assert(cfg["JavaVersion"]==j21.Version,"Automatic mode did not override old manual path");
   using(var c=new CancellationTokenSource()){c.Cancel();bool cancelled=false;try{JavaManager.ScanFolders(new[]{root},8,c.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled,"Java scan ignored cancellation");}
   string json="[{\"version\":{\"major\":8,\"semver\":\"8.0.504+1\"},\"binary\":{\"architecture\":\"x64\",\"os\":\"windows\",\"image_type\":\"jre\",\"package\":{\"name\":\"java.zip\",\"link\":\"https://github.com/adoptium/temurin8-binaries/releases/download/jdk8/test.zip\",\"size\":4096,\"checksum\":\""+new string('a',64)+"\"}}}]";var release=JavaDownload.Parse(json,8);Assert(release.Major==8&&release.Size==4096,"Adoptium release metadata failed");Denied(()=>JavaDownload.Parse(json.Replace("https://github.com/adoptium/temurin8-binaries","https://evil.example/adoptium/temurin8-binaries"),8),"Non-official Java download accepted");
   string zip=Path.Combine(root,"fixture.zip"),home=Path.Combine(root,"zip-fixture");Fake(home,8);using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create)){archive.CreateEntryFromFile(Path.Combine(home,"release"),"jre/release");archive.CreateEntryFromFile(Path.Combine(home,"bin","javaw.exe"),"jre/bin/javaw.exe");}var downloaded=JavaDownload.Extract(root,zip,release,Path.Combine(root,"extract"),new Quiet(),CancellationToken.None);Assert(downloaded.Major==8&&downloaded.Path.StartsWith(runtime+Path.DirectorySeparatorChar),"Java extraction did not install under runtime");string original=LauncherUpdateCore.HashFile(j21.Path);string attack=Path.Combine(root,"attack.zip");using(var archive=ZipFile.Open(attack,ZipArchiveMode.Create))using(var w=new StreamWriter(archive.CreateEntry("../outside.txt").Open()))w.Write("escape");Denied(()=>JavaDownload.Extract(root,attack,release,Path.Combine(root,"reject"),new Quiet(),CancellationToken.None),"Java ZIP traversal accepted");Assert(!File.Exists(Path.Combine(root,"outside.txt"))&&LauncherUpdateCore.HashFile(j21.Path)==original,"Java install touched unrelated runtime");
   Search(root);
   Console.WriteLine("PASS: Chinese name reverse search/filter/unknown names; Java inventory, portable manual/automatic policy, every-launch compatibility, missing/x86 guards, Adoptium validation, safe extraction and existing-runtime preservation.");
  }
  sealed class Quiet:IProgress<Update>{public void Report(Update u){}}
  static void Search(string root){var names=new ModNameTranslations(Path.Combine(root,"names"));Assert(names.SearchSlugs("modrinth","钠")[0]=="sodium"&&names.SearchSlugs("curseforge","鼠标手势").Contains("mouse-tweaks"),"Chinese lookup did not resolve provider slug");string last="";var api=new CatalogService((url,ct)=>{last=Uri.UnescapeDataString(url);return System.Threading.Tasks.Task.FromResult("{\"hits\":[{\"project_id\":\"wanted\",\"slug\":\"mouse-tweaks\",\"title\":\"Mouse Tweaks\",\"project_type\":\"mod\"},{\"project_id\":\"wrong\",\"slug\":\"irrelevant\",\"title\":\"Wrong\",\"project_type\":\"mod\"}],\"total_hits\":2}");});var q=new CatalogQuery{Source="modrinth",Text="鼠标手势",Game="1.20.1",Loader="forge",Category="library"};var result=api.Search(q,CancellationToken.None,names).GetAwaiter().GetResult();Assert(result.Projects.Length==1&&result.Projects[0].Id=="wanted"&&last.Contains("query=mouse-tweaks")&&last.Contains("versions:1.20.1")&&last.Contains("categories:forge")&&last.Contains("categories:library")&&q.Text=="鼠标手势","Chinese search lost compatibility filters or included unrelated hits");last="";q.Text="无此名字测试";result=api.Search(q,CancellationToken.None,names).GetAwaiter().GetResult();Assert(result.Projects.Length==0&&last=="","Unknown Chinese name searched unrelated projects");}
 }
